svg.script:
var KEY = 'svgNotes';
var t = document.getElementById('t');
var s = document.getElementById('s');
var timer;

// load saved text
try { var saved = localStorage.getItem(KEY); if (saved) t.value = saved; } catch (e) {}

// autosave while typing
t.addEventListener('input', function () {
  s.textContent = 'Saving...';
  clearTimeout(timer);
  timer = setTimeout(function () {
    try { localStorage.setItem(KEY, t.value); s.textContent = 'Saved'; }
    catch (e) { s.textContent = "Couldn't save (storage blocked)"; }
  }, 400);
});

// download as a .txt file
document.getElementById('dl').addEventListener('click', function () {
  var blob = new Blob([t.value], { type: 'text/plain' });
  var a = document.createElementNS('http://www.w3.org/1999/xhtml', 'a');
  a.href = URL.createObjectURL(blob);
  a.download = 'notes.txt';
  a.click();
  URL.revokeObjectURL(a.href);
});
